@router.get('/api/documents/{doc_id}/audit-log.csv')
def export_document_audit_csv(
    doc_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user)
):
    doc = db.query(Document).filter(Document.id == doc_id, Document.owner_id == user.id).first()
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")

    logs = db.query(DocumentAuditLog).filter(DocumentAuditLog.document_id == doc_id).all()
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(["timestamp", "action", "actor_ip", "metadata"])
    for log in logs:
        writer.writerow([log.timestamp, log.action, log.actor_ip, log.metadata])
    output.seek(0)

    return StreamingResponse(iter([output.getvalue()]), media_type="text/csv")
